#!/usr/bin/env python
# -*- coding: utf-8 -*-

import ast
import enum
import functools
import inspect
import pprint
import sys
import warnings
from contextlib import contextmanager
from datetime import datetime
from os.path import basename, realpath
from textwrap import dedent
from types import FrameType
from typing import Any, Callable, Generator, List, Literal, Optional, Sequence, Tuple, Type, Union, cast

import colorama
import executing
from pygments import highlight
from pygments.formatters import Terminal256Formatter
from pygments.lexers import Python3Lexer as Py3Lexer

from .coloring import SolarizedDark


class Sentinel(enum.Enum):
    absent = object()


def bindStaticVariable(name: str, value: Any) -> Callable[[Callable[..., Any]], Callable[..., Any]]:
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        setattr(fn, name, value)
        return fn

    return decorator


def has_non_ascii_chars(s: str) -> bool:
    return any(ord(char) > 127 for char in s)


@bindStaticVariable("formatter", Terminal256Formatter(style=SolarizedDark))
@bindStaticVariable("lexer", Py3Lexer(ensurenl=False))
def colorize(s: str) -> str:
    self = colorize
    if has_non_ascii_chars(s):
        return s
    return highlight(
        s,
        cast(Py3Lexer, self.lexer),
        cast(Terminal256Formatter, self.formatter),
    )


@contextmanager
def supportTerminalColorsInWindows() -> Generator[None, None, None]:
    if sys.platform.startswith("win"):
        colorama.init()
        try:
            yield
        finally:
            colorama.deinit()
    else:
        yield


